const raw = $json.text ?? $json.content ?? $json.message ?? $json;
const s = typeof raw === "string" ? raw : JSON.stringify(raw);
function extractJson(str){ const a = str.indexOf("{"), b = str.lastIndexOf("}"); if(a===-1||b===-1) throw new Error("No JSON found"); return str.slice(a,b+1); }
let qa; try { qa = JSON.parse(s); } catch { qa = JSON.parse(extractJson(s)); }
const verdict = (qa.verdict || "").toUpperCase();
const required_fixes = Array.isArray(qa.required_fixes) ? qa.required_fixes : [];
return [{ json: { ...$json, qa: { verdict: verdict === "PASS" ? "PASS" : "FAIL", issues: qa.issues || [], required_fixes, proof_checklist: qa.proof_checklist || [] } } }];

const iteration = ($json.iteration ?? 0) + 1;
if (iteration > 2) {
  return [{ json: { ...$json, iteration, loop_stopped: true, loop_reason: "Max iterations reached", qa_fixes_required: $json.qa.required_fixes || [] } }];
}
return [{ json: { ...$json, iteration, qa_fixes_required: $json.qa.required_fixes || [] } }];
